/* ============================================
   LearnForge — Corporate Website Styles
   ============================================ */

/* CSS Variables */
:root {
  --color-primary: #000000;
  --color-accent: #E6FF32;
  --color-burgundy: #7F2A23;
  --color-white: #ffffff;
  --color-gray-50: #fafafa;
  --color-gray-100: #f5f5f5;
  --color-gray-200: #e5e5e5;
  --color-gray-300: #d4d4d4;
  --color-gray-400: #a3a3a3;
  --color-gray-500: #737373;
  --color-gray-600: #525252;
  --color-gray-700: #404040;
  --color-gray-800: #262626;
  --color-gray-900: #171717;

  --font-heading: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.12);
  --shadow-xl: 0 24px 48px rgba(0,0,0,0.15);

  --transition-fast: 0.15s ease;
  --transition-base: 0.25s ease;
  --transition-slow: 0.4s ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background: var(--color-white);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-primary);
  letter-spacing: -0.02em;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .container {
    padding: 0 32px;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 48px;
  }
}

/* ============================================
   Navigation
   ============================================ */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-gray-200);
  transition: box-shadow var(--transition-base);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo-mark {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-links {
  display: none;
  align-items: center;
  gap: 4px;
}

.nav-link {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-gray-600);
  padding: 8px 14px;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.nav-link:hover {
  color: var(--color-primary);
  background: var(--color-gray-100);
}

.nav-link.active {
  color: var(--color-primary);
  background: var(--color-gray-100);
}

.nav-cta {
  display: none;
  font-size: 0.875rem;
  font-weight: 600;
  padding: 10px 20px;
  background: var(--color-primary);
  color: var(--color-white);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.nav-cta:hover {
  background: var(--color-gray-800);
  transform: translateY(-1px);
}

.nav-mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  transition: all var(--transition-base);
}

.nav-mobile-menu {
  display: none;
  position: absolute;
  top: 72px;
  left: 0;
  right: 0;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-200);
  padding: 16px 24px 24px;
  box-shadow: var(--shadow-lg);
}

.nav-mobile-menu.open {
  display: block;
}

.nav-mobile-link {
  display: block;
  padding: 12px 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-700);
  border-bottom: 1px solid var(--color-gray-100);
}

.nav-mobile-link:last-child {
  border-bottom: none;
}

.nav-mobile-cta {
  display: block;
  width: 100%;
  margin-top: 16px;
  text-align: center;
  padding: 14px;
  background: var(--color-primary);
  color: var(--color-white);
  font-weight: 600;
  border-radius: var(--radius-full);
}

@media (min-width: 1024px) {
  .nav-links { display: flex; }
  .nav-cta { display: inline-block; }
  .nav-mobile-toggle { display: none; }
  .nav-mobile-menu { display: none !important; }
}

/* ============================================
   Buttons
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 0.9375rem;
  font-weight: 600;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background: var(--color-gray-800);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-primary);
}

.btn-accent:hover {
  filter: brightness(0.95);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-gray-300);
}

.btn-outline:hover {
  border-color: var(--color-primary);
  background: var(--color-gray-50);
}

.btn-white {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn-white:hover {
  background: var(--color-gray-100);
  transform: translateY(-2px);
}

/* ============================================
   Hero Section
   ============================================ */
.hero {
  padding: 140px 0 80px;
  background: var(--color-white);
  position: relative;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  top: 0;
  right: 0;
  width: 60%;
  height: 100%;
  background: linear-gradient(135deg, var(--color-gray-50) 0%, var(--color-white) 100%);
  border-radius: 0 0 0 120px;
  z-index: 0;
}

.hero-inner {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 48px;
  align-items: center;
}

@media (min-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr 1fr;
    gap: 64px;
  }
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-burgundy);
  background: rgba(127,42,35,0.08);
  padding: 6px 14px;
  border-radius: var(--radius-full);
  margin-bottom: 20px;
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: 20px;
}

.hero-title span {
  color: var(--color-burgundy);
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--color-gray-500);
  line-height: 1.7;
  margin-bottom: 32px;
  max-width: 520px;
}

.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 40px;
}

.hero-tabs {
  display: inline-flex;
  background: var(--color-gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  gap: 4px;
}

.hero-tab {
  font-size: 0.8125rem;
  font-weight: 600;
  padding: 8px 16px;
  border-radius: var(--radius-full);
  color: var(--color-gray-500);
  transition: all var(--transition-fast);
}

.hero-tab:hover {
  color: var(--color-primary);
}

.hero-tab.active {
  background: var(--color-white);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.hero-visual {
  position: relative;
}

.hero-visual-frame {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
  border: 1px solid var(--color-gray-200);
}

.hero-visual-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-gray-100);
}

.hero-visual-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.hero-visual-dot.red { background: #ff5f57; }
.hero-visual-dot.yellow { background: #febc2e; }
.hero-visual-dot.green { background: #28c840; }

.hero-visual-body {
  padding: 24px;
  min-height: 320px;
}

.hero-view {
  display: none;
}

.hero-view.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Mock dashboard UI for creator view */
.mock-dashboard {
  display: grid;
  gap: 16px;
}

.mock-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.mock-card {
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  padding: 16px;
}

.mock-card h4 {
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-gray-400);
  margin-bottom: 8px;
}

.mock-card .mock-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
}

.mock-chart {
  height: 120px;
  background: linear-gradient(180deg, rgba(230,255,50,0.3) 0%, rgba(230,255,50,0.05) 100%);
  border-radius: var(--radius-md);
  position: relative;
  overflow: hidden;
}

.mock-chart::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60%;
  background: linear-gradient(90deg, transparent 0%, rgba(230,255,50,0.4) 50%, transparent 100%);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
}

.mock-table-row {
  display: flex;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid var(--color-gray-100);
  font-size: 0.8125rem;
}

.mock-table-row:last-child {
  border-bottom: none;
}

/* Mock student view */
.mock-student {
  text-align: center;
  padding: 32px 16px;
}

.mock-student-avatar {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--color-accent), #c8e600);
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
}

.mock-progress {
  margin-top: 24px;
  text-align: left;
}

.mock-progress-item {
  margin-bottom: 16px;
}

.mock-progress-item span {
  font-size: 0.8125rem;
  font-weight: 500;
  display: block;
  margin-bottom: 6px;
}

.mock-progress-bar {
  height: 8px;
  background: var(--color-gray-100);
  border-radius: var(--radius-full);
  overflow: hidden;
}

.mock-progress-fill {
  height: 100%;
  background: var(--color-accent);
  border-radius: var(--radius-full);
}

/* ============================================
   Stats Bar
   ============================================ */
.stats-bar {
  background: var(--color-primary);
  color: var(--color-white);
  padding: 48px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 32px;
  text-align: center;
}

@media (min-width: 640px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--color-accent);
  margin-bottom: 8px;
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--color-gray-400);
  font-weight: 500;
}

/* ============================================
   Section Styles
   ============================================ */
.section {
  padding: 80px 0;
}

@media (min-width: 1024px) {
  .section { padding: 120px 0; }
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 56px;
}

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-burgundy);
  margin-bottom: 16px;
}

.section-title {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  margin-bottom: 16px;
}

.section-desc {
  font-size: 1.0625rem;
  color: var(--color-gray-500);
  line-height: 1.7;
}

/* ============================================
   Products Grid
   ============================================ */
.products-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 24px;
}

@media (min-width: 640px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
}

.product-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

.product-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.product-card:hover::before {
  transform: scaleX(1);
}

.product-icon {
  width: 48px;
  height: 48px;
  background: var(--color-gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 1.25rem;
}

.product-card h3 {
  font-size: 1.125rem;
  margin-bottom: 8px;
}

.product-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ============================================
   Why Choose Us — Tabs
   ============================================ */
.why-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  margin-bottom: 48px;
}

.why-tab {
  font-size: 0.875rem;
  font-weight: 600;
  padding: 12px 20px;
  border-radius: var(--radius-full);
  background: var(--color-gray-100);
  color: var(--color-gray-600);
  transition: all var(--transition-fast);
  cursor: pointer;
  border: none;
}

.why-tab:hover {
  background: var(--color-gray-200);
}

.why-tab.active {
  background: var(--color-primary);
  color: var(--color-white);
}

.why-content {
  display: none;
}

.why-content.active {
  display: block;
  animation: fadeIn 0.35s ease;
}

.why-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 24px;
}

@media (min-width: 768px) {
  .why-grid { grid-template-columns: repeat(2, 1fr); }
}

.why-feature {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-gray-100);
}

.why-feature-icon {
  width: 40px;
  height: 40px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1rem;
}

.why-feature h4 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.why-feature p {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

/* ============================================
   Global Scale / AI / Feature Sections
   ============================================ */
.feature-split {
  display: grid;
  gap: 48px;
  align-items: center;
}

@media (min-width: 1024px) {
  .feature-split {
    grid-template-columns: 1fr 1fr;
    gap: 80px;
  }
  .feature-split.reverse {
    direction: rtl;
  }
  .feature-split.reverse > * {
    direction: ltr;
  }
}

.feature-visual {
  background: var(--color-gray-50);
  border-radius: var(--radius-xl);
  padding: 40px;
  border: 1px solid var(--color-gray-200);
  position: relative;
  overflow: hidden;
}

.feature-visual::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -50%;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle, rgba(230,255,50,0.15) 0%, transparent 70%);
}

.feature-list {
  display: grid;
  gap: 20px;
  margin-top: 32px;
}

.feature-list-item {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.feature-list-check {
  width: 24px;
  height: 24px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 0.75rem;
  font-weight: 700;
}

.feature-list-item h4 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.feature-list-item p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
}

/* ============================================
   Testimonials Carousel
   ============================================ */
.testimonials-section {
  background: var(--color-gray-50);
}

.testimonials-carousel {
  position: relative;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 0 12px;
}

@media (min-width: 768px) {
  .testimonial-card { flex: 0 0 50%; }
}

@media (min-width: 1024px) {
  .testimonial-card { flex: 0 0 33.333%; }
}

.testimonial-inner {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--color-gray-200);
  height: 100%;
  display: flex;
  flex-direction: column;
}

.testimonial-quote {
  font-size: 1.0625rem;
  line-height: 1.7;
  color: var(--color-gray-700);
  margin-bottom: 24px;
  flex-grow: 1;
  position: relative;
  padding-left: 20px;
  border-left: 3px solid var(--color-accent);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 14px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-accent), #c8e600);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.875rem;
  color: var(--color-primary);
}

.testimonial-author-info h4 {
  font-size: 0.9375rem;
  margin-bottom: 2px;
}

.testimonial-author-info span {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
}

.testimonial-tag {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-burgundy);
  background: rgba(127,42,35,0.08);
  padding: 4px 10px;
  border-radius: var(--radius-full);
  margin-bottom: 12px;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 40px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  transition: all var(--transition-fast);
  cursor: pointer;
  border: none;
  padding: 0;
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: var(--radius-full);
}

/* ============================================
   Pricing Overview
   ============================================ */
.pricing-cards {
  display: grid;
